def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0 = min(r for r, c in marked)
    r1 = max(r for r, c in marked)
    c0 = min(c for r, c in marked)
    c1 = max(c for r, c in marked)
    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            candidates = []
            rr = 31 - r
            cc = 31 - c
            if 0 <= rr < h and grid[rr][c] != 8:
                candidates.append(grid[rr][c])
            if 0 <= cc < w and grid[r][cc] != 8:
                candidates.append(grid[r][cc])
            if candidates:
                row.append(candidates[0])
            else:
                nearby = []
                for distance in range(1, 5):
                    for rr in (r - distance, r + distance):
                        if 0 <= rr < h and grid[rr][c] != 8:
                            nearby.append((distance, grid[rr][c]))
                if nearby:
                    nearest_distance = min(distance for distance, value in nearby)
                    nearest = [value for distance, value in nearby if distance == nearest_distance]
                    row.append(max(set(nearest), key=nearest.count))
                else:
                    row.append(8)
        out.append(row)
    return out

